create type public.app_role as enum ('owner','project_manager','site_lead','supplier','viewer');
create type public.project_status as enum ('planning','permitting','active','paused','complete');
create type public.material_status as enum ('specified','ordered','delivered','installed','reused','recycled');
create type public.task_status as enum ('todo','in_progress','blocked','done');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role app_role not null default 'viewer', company text, avatar_url text, created_at timestamptz default now());
create table public.projects (id uuid primary key default gen_random_uuid(), name text not null, code text unique not null, status project_status not null default 'planning', address text not null, budget numeric not null default 0, start_date date, target_date date, diversion_goal numeric not null default 90, created_at timestamptz default now());
create table public.project_members (project_id uuid references public.projects(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role app_role not null, primary key(project_id,user_id));
create table public.materials (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id) on delete cascade, name text not null, category text not null, status material_status not null default 'specified', quantity numeric not null, unit text not null, embodied_carbon_kg numeric default 0, circularity_score numeric check (circularity_score between 0 and 100), supplier text, created_at timestamptz default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id) on delete cascade, title text not null, status task_status not null default 'todo', priority text not null default 'medium', assignee_id uuid references public.profiles(id), due_date date, created_at timestamptz default now());
create table public.documents (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id) on delete cascade, name text not null, path text not null, type text not null, uploaded_by uuid references public.profiles(id), created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.materials enable row level security; alter table public.tasks enable row level security; alter table public.documents enable row level security;
create or replace function public.current_role() returns app_role language sql stable security definer as $$ select role from public.profiles where id = auth.uid() $$;
create policy "profiles self or admins" on public.profiles for select using (id=auth.uid() or public.current_role() in ('owner','project_manager'));
create policy "project read members" on public.projects for select using (public.current_role() in ('owner','project_manager') or exists(select 1 from public.project_members where project_id=id and user_id=auth.uid()));
create policy "project write managers" on public.projects for all using (public.current_role() in ('owner','project_manager')) with check (public.current_role() in ('owner','project_manager'));
create policy "members read" on public.project_members for select using (user_id=auth.uid() or public.current_role() in ('owner','project_manager'));
create policy "materials read" on public.materials for select using (exists(select 1 from public.projects p where p.id=project_id));
create policy "materials write" on public.materials for all using (public.current_role() in ('owner','project_manager','site_lead','supplier')) with check (public.current_role() in ('owner','project_manager','site_lead','supplier'));
create policy "tasks read" on public.tasks for select using (exists(select 1 from public.projects p where p.id=project_id));
create policy "tasks write" on public.tasks for all using (public.current_role() in ('owner','project_manager','site_lead')) with check (public.current_role() in ('owner','project_manager','site_lead'));
create policy "docs read" on public.documents for select using (exists(select 1 from public.projects p where p.id=project_id));
create policy "docs write" on public.documents for all using (public.current_role() in ('owner','project_manager','site_lead','supplier')) with check (public.current_role() in ('owner','project_manager','site_lead','supplier'));
insert into storage.buckets (id, name, public) values ('project-documents','project-documents',false) on conflict do nothing;
create policy "document storage authenticated" on storage.objects for all using (bucket_id='project-documents' and auth.role()='authenticated') with check (bucket_id='project-documents' and auth.role()='authenticated');
alter publication supabase_realtime add table public.projects; alter publication supabase_realtime add table public.materials; alter publication supabase_realtime add table public.tasks; alter publication supabase_realtime add table public.documents;
